package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type DateRec struct {
	DtId   string
	DtYyyy int64
	DtMm   int64
	DtDd   int64
}

var WsEofFlag string = "N"
var WsLeapFlag string = "N"
var WsQ int64 = 0
var WsR4 int64 = 0
var WsR100 int64 = 0
var WsR400 int64 = 0
var WsMaxDay int64 = 0
var WsValid int64 = 0
var WsBadMonth int64 = 0
var WsBadDay int64 = 0

var dateRec DateRec
var dateFileReader *bufio.Scanner
var dateFile *os.File
var _ = decimal.Decimal{}

func formatInt(v int64, digits int) string {
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	if digits > 0 {
		v = v % mod
		if v < 0 {
			v += mod
		}
	}
	s := fmt.Sprintf("%d", v)
	if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	} else if len(s) > digits {
		s = s[len(s)-digits:]
	}
	return s
}

func parseInt(s string, scale int) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	var n int64
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			n = n*10 + int64(ch-'0')
		}
	}
	_ = scale
	return n
}

func padRight(s string, n int) string {
	if len(s) > n {
		return s[:n]
	}
	if len(s) < n {
		return s + strings.Repeat(" ", n-len(s))
	}
	return s
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}
func isLeap() bool {
	return WsLeapFlag == "Y"
}

func main() {
	var err error
	dateFile, err = os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			dateFile = nil
			dateFileReader = nil
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	}
	if dateFile != nil {
		dateFileReader = bufio.NewScanner(dateFile)
		// allow long lines
		buf := make([]byte, 0, 64*1024)
		dateFileReader.Buffer(buf, 10*1024*1024)
	}

	MAIN_PARA()

	if dateFile != nil {
		dateFile.Close()
	}
}

func MAIN_PARA() {
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	// CLOSE DATE-FILE already handled
	fmt.Printf("%s%s%s%s%s%s%s\n", "VALID: ", formatInt(WsValid, 2), " BAD MONTH: ", formatInt(WsBadMonth, 2), " BAD DAY: ", formatInt(WsBadDay, 2))
}

func READ_PARA() {
	if dateFileReader == nil {
		WsEofFlag = "Y"
		return
	}
	if dateFileReader.Scan() {
		line := dateFileReader.Text()
		if len(line) < 12 {
			line = line + strings.Repeat(" ", 12-len(line))
		}
		if len(line) > 12 {
			line = line[:12]
		}
		dateRec.DtId = line[0:4]
		dateRec.DtYyyy = parseInt(line[4:8], 0)
		dateRec.DtMm = parseInt(line[8:10], 0)
		dateRec.DtDd = parseInt(line[10:12], 0)
	} else {
		WsEofFlag = "Y"
	}
}

func PROCESS_PARA() {
	LEAP_PARA()
	if dateRec.DtMm < 1 || dateRec.DtMm > 12 {
		WsBadMonth = (WsBadMonth + 1) % 100
		fmt.Printf("%s%s%s\n", padRight(dateRec.DtId, 4), " BAD MONTH ", formatInt(dateRec.DtMm, 2))
	} else {
		DAYS_PARA()
		if dateRec.DtDd < 1 || dateRec.DtDd > WsMaxDay {
			WsBadDay = (WsBadDay + 1) % 100
			fmt.Printf("%s%s%s%s%s\n", padRight(dateRec.DtId, 4), " BAD DAY ", formatInt(dateRec.DtDd, 2), " MAX ", formatInt(WsMaxDay, 2))
		} else {
			WsValid = (WsValid + 1) % 100
			fmt.Printf("%s%s%s%s%s%s%s\n", padRight(dateRec.DtId, 4), " VALID ", formatInt(dateRec.DtYyyy, 4), "-", formatInt(dateRec.DtMm, 2), "-", formatInt(dateRec.DtDd, 2))
		}
	}
	READ_PARA()
}

func LEAP_PARA() {
	WsQ = dateRec.DtYyyy / 4
	WsR4 = dateRec.DtYyyy % 4
	WsQ = dateRec.DtYyyy / 100
	WsR100 = dateRec.DtYyyy % 100
	WsQ = dateRec.DtYyyy / 400
	WsR400 = dateRec.DtYyyy % 400
	WsQ = WsQ % 10000
	WsR4 = WsR4 % 1000
	WsR100 = WsR100 % 1000
	WsR400 = WsR400 % 1000
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DAYS_PARA() {
	switch dateRec.DtMm {
	case 2:
		if isLeap() {
			WsMaxDay = 29
		} else {
			WsMaxDay = 28
		}
	case 4, 6, 9, 11:
		WsMaxDay = 30
	default:
		WsMaxDay = 31
	}
	WsMaxDay = WsMaxDay % 100
}

